import json, sqlite3, sys, re
from pathlib import Path

programs_path, out_path = sys.argv[1:]
db_path = Path('assets/data/career_path.db').resolve()
conn = sqlite3.connect(f'file:{db_path}?mode=ro', uri=True)
rows = conn.execute('select id, slug, name, parent_id from career_nodes').fetchall()
nodes = {r[0]: {'career_node_id': r[0], 'career_node_slug': r[1], 'name': r[2], 'parent_id': r[3]} for r in rows}

def breadcrumb(node_id):
    chain=[]
    seen=set()
    cur=node_id
    while cur is not None and cur not in seen:
        seen.add(cur)
        n=nodes[cur]
        chain.append(n['name'])
        cur=n['parent_id']
    return ' > '.join(reversed(chain))

for n in nodes.values():
    n['breadcrumb']=breadcrumb(n['career_node_id'])

# node id, relation label, confidence

def mp(node_id, relation='direct discipline', confidence='high'):
    n=nodes[node_id]
    return {
        'career_node_id': node_id,
        'career_node_slug': n['career_node_slug'],
        'career_breadcrumb': n['breadcrumb'],
        'relation': relation,
        'confidence': confidence,
        'mapping_status': 'reviewed_against_local_tree'
    }

def choose(fac, level, name):
    l=name.lower()
    # Engineering and IT
