        if 'computer application' in l: return mp(93 if level in ('PG','PHD') else 3, 'direct discipline: computer applications', 'high')
        if 'computer science' in l: return mp(80, 'direct discipline: computer science', 'high')
        if 'electronics' in l: return mp(82, 'direct discipline: electronics and communication', 'high')
        if 'electrical' in l:
            if 'power system' in l or 'power & drives' in l: return mp(324, 'direct specialization: power systems', 'high')
            if 'control' in l: return mp(325, 'direct specialization: control systems', 'high')
            if 'renewable' in l: return mp(362, 'direct specialization: renewable energy', 'high')
            if 'electric vehicle' in l: return mp(361, 'direct specialization: electric vehicle powertrain', 'high')
            return mp(85, 'direct discipline: electrical engineering', 'high')
        if 'mechanical' in l:
            if 'automobile' in l or 'electric vehicle' in l: return mp(318, 'direct specialization: automobile/electric vehicle engineering', 'high')
            return mp(83, 'direct discipline: mechanical engineering', 'high')
        if 'civil' in l:
            if 'structural' in l: return mp(321, 'direct specialization: structural engineering', 'high')
            if 'environmental' in l: return mp(367, 'nearest specialization: green/environmental engineering', 'medium')
            return mp(84, 'direct discipline: civil engineering', 'high')
        if 'biomedical' in l: return mp(339, 'nearest parent: paramedical and health sciences', 'medium')
        if 'biochemical' in l: return mp(86, 'nearest parent: chemical engineering', 'medium')
        if 'bioinformatics' in l: return mp(88, 'nearest parent: biotechnology', 'medium')
        if 'biotechnology' in l: return mp(88, 'direct discipline: biotechnology', 'high')
        if 'food' in l or 'processing and food' in l: return mp(28 if level=='UG' else 161, 'direct discipline: food technology', 'high')
        if 'production' in l or 'industrial engineering' in l: return mp(1, 'nearest parent: B.Tech / B.E. engineering', 'medium')
        if 'bench work' in l: return mp(80, 'nearest parent: computer science', 'low')
        return mp(1, 'nearest parent: B.Tech / B.E. engineering', 'low')
