    if 'pharmacy' in fac.lower():
        if level in ('PG','PHD') or 'pharm. d' in l or 'master of pharmacy' in l or 'doctor of philosophy' in l:
            return mp(144, 'direct discipline: pharmaceutical research', 'high')
        return mp(143, 'direct discipline: clinical pharmacy', 'high')
    # Architecture, planning and design
    if 'architecture' in fac.lower():
        if 'planning' in l: return mp(234, 'direct discipline: urban planning', 'high')
        if 'fashion' in l: return mp(230, 'direct discipline: fashion design', 'high')
        if 'product' in l: return mp(232, 'direct discipline: product design', 'high')
        if 'interior' in l: return mp(233, 'direct discipline: interior design', 'high')
        if 'communication design' in l or 'ui/ux' in l: return mp(229, 'direct discipline: UX/UI design', 'high')
        return mp(105, 'direct discipline: architecture', 'high')
    # Science
    if fac.lower().endswith('science'):
        if 'biochemistry' in l: return mp(180 if level in ('PG','PHD') else 35, 'direct discipline: biochemistry', 'high')
        if 'biotechnology' in l: return mp(146 if level in ('PG','PHD') else 21, 'direct discipline: biotechnology', 'high')
