        if 'environmental' in l or 'disaster risk' in l: return mp(157, 'nearest specialization: environmental science', 'medium')
        if 'life sciences' in l or 'botany' in l or 'zoology' in l: return mp(21, 'nearest parent: biology / biotechnology', 'medium')
        if 'data science' in l: return mp(31, 'direct discipline: data science', 'high')
        return mp(336, 'nearest parent: Biology / PCB', 'low')
    # Medicine and allied health
    if 'medicine' in fac.lower() or 'health sciences' in fac.lower():
        if 'mbbs' in l or 'medicine and bachelor of surgery' in l: return mp(15, 'direct discipline: MBBS', 'high')
        if 'physiotherapy' in l: return mp(151, 'direct discipline: physiotherapy', 'high')
        if 'optometry' in l: return mp(183, 'direct discipline: optometry', 'high')
        if 'radiology' in l or 'radiological' in l or 'mr it' in l or 'mrit' in l or 'ct scan' in l or 'mri technician' in l or 'x ray' in l: return mp(188, 'direct discipline: radiology and imaging', 'high')
        if 'medical lab' in l or 'laboratory' in l or 'dmlt' in l: return mp(185, 'direct discipline: medical laboratory technology', 'high')
        if 'forensic' in l: return mp(159, 'direct discipline: forensic science', 'high')
        if 'psychiatry' in l or 'clinical psychology' in l: return mp(266, 'direct discipline: psychology', 'high')
        if 'microbiology' in l: return mp(177, 'direct discipline: microbiology', 'high')
        if 'biochemistry' in l: return mp(180, 'direct discipline: biochemistry', 'high')
        if 'pharmacology' in l: return mp(144, 'direct discipline: pharmaceutical research', 'medium')
        if 'nutrition' in l or 'dietetic' in l or 'public health' in l or 'community medicine' in l: return mp(339, 'nearest parent: paramedical and health sciences', 'medium')
        if 'hospital administration' in l: return mp(342, 'nearest parent: management and business', 'medium')
        if 'anatomy' in l or 'physiology' in l: return mp(339, 'nearest parent: paramedical and health sciences', 'medium')
        if 'anaesthesia' in l or 'anesthesia' in l or 'operation theatre' in l or 'operation theater' in l or 'dialysis' in l or 'respiratory' in l or 'cardiovascular' in l or 'blood banking' in l: return mp(339, 'nearest parent: paramedical and health sciences', 'medium')
        if 'surgery' in l or 'obstetrics' in l or 'ophthalmology' in l or 'ot o-rhino' in l or 'general medicine' in l or 'dermatology' in l or 'pathology' in l: return mp(128 if level=='PG' else 15, 'nearest parent: medical sciences', 'medium')
        return mp(339, 'nearest parent: paramedical and health sciences', 'low')
    # Education
    if fac.lower().endswith('education'):
        if 'guidance' in l or 'counselling' in l: return mp(267, 'direct discipline: counselling', 'high')
        return mp(69 if 'education' in l or level in ('UG','PG','PHD') else 275, 'direct discipline: education', 'high')
    # Humanities and social sciences
    if 'humanities' in fac.lower():
        if 'english' in l: return mp(72 if level=='UG' else 285, 'direct discipline: English', 'high')
        if 'arabic' in l or 'french' in l or 'german' in l: return mp(74, 'direct discipline: foreign languages', 'high')
        if 'urdu' in l or 'hindi' in l: return mp(73, 'direct discipline: Hindi / regional language', 'high')
        if 'economics' in l: return mp(68 if level=='UG' else 272, 'direct discipline: economics', 'high')
        if 'history' in l: return mp(70 if level=='UG' else 278, 'direct discipline: history', 'high')
        if 'political' in l or 'international relations' in l: return mp(71 if level=='UG' else 281, 'direct discipline: political science', 'high')
        if 'psychology' in l or 'guidance' in l: return mp(66 if level=='UG' else 266, 'direct discipline: psychology', 'high')
        if 'sociology' in l or 'social work' in l: return mp(67 if level=='UG' else 269, 'direct discipline: sociology and social work', 'high')
        if 'journalism' in l or 'mass communication' in l or 'j&mc' in l: return mp(59, 'direct discipline: journalism and mass communication', 'high')
        if 'digital' in l or 'broadcast' in l: return mp(62, 'direct discipline: digital media', 'high')
        if 'human rights' in l: return mp(343, 'nearest parent: law and legal', 'medium')
        if 'liberal arts' in l: return mp(348, 'nearest parent: social sciences and education', 'medium')
        return mp(348, 'nearest parent: social sciences and education', 'low')
    # Law and polytechnic entries are combined on the official page
    if 'law' in fac.lower():
        if 'criminal law' in l: return mp(255, 'direct discipline: criminal law', 'high')
        if 'international law' in l: return mp(343, 'direct discipline: law and legal', 'high')
        if 'bachelor of arts' in l: return mp(63, 'direct discipline: BA LLB', 'high')
        if 'business administration - bachelor of law' in l: return mp(50, 'direct discipline: BBA LLB', 'high')
        if l == 'bachelor of law': return mp(343, 'direct discipline: law and legal', 'high')
        if 'carpentry' in l or 'welding' in l: return mp(115, 'nearest specialization: mechanical technician', 'medium')
        if 'electrician' in l: return mp(118, 'direct specialization: electrical technician', 'high')
        if 'surveyor' in l or 'civil engineering' in l: return mp(116, 'direct specialization: civil site supervision', 'high')
        if 'computer' in l or 'networking' in l: return mp(333, 'direct specialization: network engineering', 'high')
        if 'two-wheeler' in l or 'mechanical engineering' in l: return mp(318, 'direct specialization: automobile engineering', 'high')
        return mp(343, 'nearest parent: law and legal', 'medium')
    # Agriculture
    if 'agricultural' in fac.lower():
        if 'business administration' in l: return mp(209, 'nearest specialization: agribusiness management', 'medium')
        if 'agricultural engineering' in l or 'farm machinery' in l or 'soil and water conservation engineering' in l: return mp(30, 'nearest parent: agriculture', 'medium')
        return mp(165, 'direct discipline: agricultural science', 'high')
    # Commerce
    if fac.lower().endswith('commerce'):
        if 'hotel management' in l: return mp(79, 'direct discipline: hotel management and tourism', 'high')
        if 'fintech' in l: return mp(376, 'direct specialization: fintech', 'high')
        if 'business analytics' in l: return mp(169, 'direct specialization: business intelligence analytics', 'high')
        if 'accounting' in l or 'commerce' in l: return mp(42 if level=='UG' else 198, 'direct discipline: commerce and accounting', 'high')
        if 'retail' in l: return mp(342, 'nearest specialization: management and business', 'medium')
        return mp(340, 'nearest parent: accounting and audit', 'medium')
    # Nursing
    if 'nursing' in fac.lower(): return mp(140, 'direct discipline: nursing', 'high')
    # Integral Business School
    if 'business school' in fac.lower():
        if 'financial' in l or 'finance' in l: return mp(201, 'direct specialization: MBA/BBA finance', 'high')
        if 'business analytics' in l: return mp(169, 'direct specialization: business analytics', 'high')
        if 'travel' in l or 'tourism' in l: return mp(304, 'direct discipline: hotel management and tourism', 'high')
        if 'logistics' in l or 'supply chain' in l: return mp(209, 'nearest specialization: operations and business management', 'medium')
        return mp(208 if level in ('PG','PHD') else 46, 'direct discipline: management and business', 'high')
    return mp(342, 'nearest parent: management and business', 'low')

programs=[]
with open(programs_path, encoding='utf-8') as f:
    for i,line in enumerate(f, 1):
        fac, level, name, duration = line.rstrip('\\n').split('\\t')
        name = re.sub(r'\\s+Null\\s*"'$'"', '', name)
        name = re.sub(r'\\s+43\\s*"'$'"', '', name)
        if name == 'Doctor of Medicine in Anesthesiology':
            pass
        duration = duration.replace('2Years','2 Years')
        if 'Part Time' in name or 'Part time' in name:
            mode='part_time'
        elif 'Evening' in name:
            mode='evening'
        else:
            mode='not_stated'
        level_map={'UG':'undergraduate','PG':'postgraduate','PHD':'doctoral','DIPLOMA':'diploma','CERTIFICATE':'certificate','PG DIPLOMA':'postgraduate_diploma','PB DIPLOMA':'post_basic_diploma'}
        credential_map={'UG':'degree','PG':'degree','PHD':'doctorate','DIPLOMA':'diploma','CERTIFICATE':'certificate','PG DIPLOMA':'postgraduate_diploma','PB DIPLOMA':'post_basic_diploma'}
        mapping=choose(fac, level, name)
        programs.append({
            'course_id': f'integral-university-course-{i:03d}',
            'name': name,
            'level': level_map[level],
            'credential': credential_map[level],
            'specialization': None,
            'duration': duration,
            'mode': mode,
            'eligibility': None,
            'official_course_url': 'https://www.iul.ac.in/admissioninfo/FeeInd.aspx',
            'verification_status': 'verified',
            'career_path_mappings': [mapping] if mapping else [],
            'mapping_gap': None if mapping else 'No responsible career-tree node identified.'
        })

