def breadcrumb(node_id):
    chain=[]
    seen=set()
    cur=node_id
    while cur is not None and cur not in seen:
        seen.add(cur)
        n=nodes[cur]
        chain.append(n['name'])
        cur=n['parent_id']
    return ' > '.join(reversed(chain))

for n in nodes.values():
